#!/usr/bin/env python3
"""
A small, original jq-compatible JSON processor implementation.
It implements the command-line behavior and a practical subset of jq's
filter language sufficient for common one-liners.  It is intentionally
self-contained and uses only the Python standard library.
"""
from __future__ import annotations

import sys, os, json, re, math, time, base64, urllib.parse, csv, io
from decimal import Decimal, InvalidOperation, getcontext, ROUND_FLOOR, ROUND_CEILING
from collections import OrderedDict
from dataclasses import dataclass
from typing import Any, List, Dict, Optional, Iterable, Tuple

getcontext().prec = 80

VERSION = "jq-build-2b77eb1"
HELP_TEXT = """jq - commandline JSON processor [version build-2b77eb1]

Usage:\tjq [options] <jq filter> [file...]
\tjq [options] --args <jq filter> [strings...]
\tjq [options] --jsonargs <jq filter> [JSON_TEXTS...]

jq is a tool for processing JSON inputs, applying the given filter to
its JSON text inputs and producing the filter's results as JSON on
standard output.

The simplest filter is ., which copies jq's input to its output
unmodified except for formatting. For more advanced filters see
the jq(1) manpage ("man jq") and/or https://jqlang.org/.

Example:

\t$ echo '{"foo": 0}' | jq .
\t{
\t  "foo": 0
\t}

Command options:
  -n, --null-input          use `null` as the single input value;
  -R, --raw-input           read each line as string instead of JSON;
  -s, --slurp               read all inputs into an array and use it as
                            the single input value;
  -c, --compact-output      compact instead of pretty-printed output;
  -r, --raw-output          output strings without escapes and quotes;
      --raw-output0         implies -r and output NUL after each output;
  -j, --join-output         implies -r and output without newline after
                            each output;
  -a, --ascii-output        output strings by only ASCII characters
                            using escape sequences;
  -S, --sort-keys           sort keys of each object on output;
  -C, --color-output        colorize JSON output;
  -M, --monochrome-output   disable colored output;
      --tab                 use tabs for indentation;
      --indent n            use n spaces for indentation (max 7 spaces);
      --unbuffered          flush output stream after each output;
      --stream              parse the input value in streaming fashion;
      --stream-errors       implies --stream and report parse error as
                            an array;
      --seq                 parse input/output as application/json-seq;
  -f, --from-file           load the filter from a file;
  -L, --library-path dir    search modules from the directory;
      --arg name value      set $name to the string value;
      --argjson name value  set $name to the JSON value;
      --slurpfile name file set $name to an array of JSON values read
                            from the file;
      --rawfile name file   set $name to string contents of file;
      --args                consume remaining arguments as positional
                            string values;
      --jsonargs            consume remaining arguments as positional
                            JSON values;
  -e, --exit-status         set exit status code based on the output;
  -V, --version             show the version;
  --build-configuration     show jq's build configuration;
  -h, --help                show the help;
  --                        terminates argument processing;

Named arguments are also available as $ARGS.named[], while
positional arguments are available as $ARGS.positional[].
"""
BUILD_CONFIG = "--disable-docs --with-oniguruma=builtin --enable-static --enable-all-static --prefix=/usr/local"

# ---------------------------- JSON values ----------------------------

class JQError(Exception):
    pass

class JQCompileError(Exception):
    pass

class HaltException(Exception):
    def __init__(self, code=0, value=None):
        self.code = code
        self.value = value

class BreakException(Exception):
    pass

class JQNumber:
    __slots__ = ("raw", "dec")
    def __init__(self, raw: Any):
        if isinstance(raw, JQNumber):
            self.raw = raw.raw
            self.dec = raw.dec
            return
        if isinstance(raw, bool):
            raw = int(raw)
        if isinstance(raw, int):
            self.raw = str(raw)
            self.dec = Decimal(raw)
        elif isinstance(raw, Decimal):
            self.dec = raw
            self.raw = decimal_to_jq(raw)
        elif isinstance(raw, float):
            if math.isnan(raw):
                self.raw = "null"
                self.dec = Decimal(0)
            elif math.isinf(raw):
                self.raw = "1.7976931348623157e+308" if raw > 0 else "-1.7976931348623157e+308"
                self.dec = Decimal(self.raw)
            else:
                self.raw = repr(raw)
                self.dec = Decimal(str(raw))
        else:
            s = str(raw)
            self.raw = normalize_exp_lexeme(s)
            try:
                self.dec = Decimal(s)
            except InvalidOperation:
                self.dec = Decimal(0)
    def __repr__(self):
        return f"JQNumber({self.raw!r})"
    def __hash__(self):
        return hash(self.dec.normalize())


def normalize_exp_lexeme(s: str) -> str:
    # jq prints exponent marker as E for preserved JSON/program numeric lexemes.
    if 'e' in s and 'E' not in s:
        return s.replace('e', 'E')
    return s


def decimal_to_jq(d: Decimal) -> str:
    if d.is_nan():
        return "null"
    if d == d.to_integral_value():
        return str(int(d))
    # Use fixed notation for ordinary values, avoiding trailing zeros.
    n = d.normalize()
    # For very large/small normalized Decimals, Python may choose scientific;
    # jq accepts both.  Use a compact lowercase-e form in that case.
    s = format(n, 'f')
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    if s == "-0":
        s = "0"
    if s == "" or s == "-":
        s = "0"
    return s


def is_num(x): return isinstance(x, JQNumber)
def as_dec(x):
    if isinstance(x, JQNumber): return x.dec
    if isinstance(x, int) and not isinstance(x, bool): return Decimal(x)
    if isinstance(x, float): return Decimal(str(x))
    raise JQError(f"{type_name(x)} ({short_json(x)}) is not a number")

def make_num(d):
    if not isinstance(d, Decimal): d = Decimal(d)
    return JQNumber(d)


def deepcopy_jq(v):
    if isinstance(v, JQNumber): return JQNumber(v)
    if isinstance(v, list): return [deepcopy_jq(x) for x in v]
    if isinstance(v, dict): return OrderedDict((k, deepcopy_jq(val)) for k,val in v.items())
    return v


def normalize_for_json(v):
    if isinstance(v, JQNumber):
        # For interfacing with Python json only; not for final output.
        if v.dec == v.dec.to_integral_value(): return int(v.dec)
        return float(v.dec)
    if isinstance(v, list): return [normalize_for_json(x) for x in v]
    if isinstance(v, dict): return {str(k): normalize_for_json(val) for k,val in v.items()}
    return v


def jq_truth(v):
    return not (v is None or v is False)


def type_name(v):
    if v is None: return "null"
    if isinstance(v, bool): return "boolean"
    if isinstance(v, JQNumber): return "number"
    if isinstance(v, str): return "string"
    if isinstance(v, list): return "array"
    if isinstance(v, dict): return "object"
    return type(v).__name__


def jq_type_string(v):
    if v is None: return "null"
    if isinstance(v, bool): return "boolean"
    if isinstance(v, JQNumber): return "number"
    if isinstance(v, str): return "string"
    if isinstance(v, list): return "array"
    if isinstance(v, dict): return "object"
    return "unknown"

# ---------------------------- JSON parsing/output ----------------------------

def parse_int_hook(s): return JQNumber(s)
def parse_float_hook(s): return JQNumber(s)

class OrderedDecoder(json.JSONDecoder):
    def __init__(self):
        super().__init__(object_pairs_hook=OrderedDict, parse_int=parse_int_hook, parse_float=parse_float_hook)


def parse_one_json(text: str):
    dec = OrderedDecoder()
    val, idx = dec.raw_decode(text)
    rest = text[idx:].strip()
    if rest:
        raise ValueError("extra")
    return val


def parse_json_values(text: str) -> List[Any]:
    vals = []
    dec = OrderedDecoder()
    i, n = 0, len(text)
    while True:
        while i < n and text[i].isspace(): i += 1
        if i >= n: break
        try:
            val, j = dec.raw_decode(text, i)
        except json.JSONDecodeError as e:
            # Map only roughly to jq's diagnostics.
            if i >= n-1 and text[i] in '[{':
                raise JQError(f"parse error: Unfinished JSON term at EOF at line {e.lineno}, column {e.colno}")
            raise JQError(f"parse error: Invalid numeric literal at line {e.lineno}, column {e.colno}")
        vals.append(val)
        i = j
    return vals


def parse_json_seq(text: str) -> List[Any]:
    vals = []
    for part in text.split('\x1e'):
        if not part.strip():
            continue
        vals.extend(parse_json_values(part))
    return vals


def json_escape_string(s: str, ensure_ascii=False) -> str:
    return json.dumps(s, ensure_ascii=ensure_ascii, separators=(',', ':'))


def object_items(obj, sort_keys=False):
    items = list(obj.items())
    if sort_keys:
        items.sort(key=lambda kv: kv[0])
    return items


def dump_json(v, compact=False, ensure_ascii=False, sort_keys=False, indent=2, tab=False, level=0, color=False):
    # Compact jq JSON: no insignificant whitespace.
    if isinstance(v, JQNumber):
        return v.raw
    if v is None:
        return "null"
    if v is True:
        return "true"
    if v is False:
        return "false"
    if isinstance(v, str):
        return json_escape_string(v, ensure_ascii)
    if isinstance(v, list):
        if compact:
            return "[" + ",".join(dump_json(x, True, ensure_ascii, sort_keys, indent, tab, level+1, color) for x in v) + "]"
        if not v:
            return "[]"
        istr = '\t' if tab else (' ' * max(0, indent))
        cur = istr * level
        nxt = istr * (level+1)
        return "[\n" + ",\n".join(nxt + dump_json(x, False, ensure_ascii, sort_keys, indent, tab, level+1, color) for x in v) + "\n" + cur + "]"
    if isinstance(v, dict):
        if compact:
            return "{" + ",".join(json_escape_string(str(k), ensure_ascii) + ":" + dump_json(val, True, ensure_ascii, sort_keys, indent, tab, level+1, color) for k,val in object_items(v, sort_keys)) + "}"
        if not v:
            return "{}"
        istr = '\t' if tab else (' ' * max(0, indent))
        cur = istr * level
        nxt = istr * (level+1)
        parts = []
        for k,val in object_items(v, sort_keys):
            parts.append(nxt + json_escape_string(str(k), ensure_ascii) + ": " + dump_json(val, False, ensure_ascii, sort_keys, indent, tab, level+1, color))
        return "{\n" + ",\n".join(parts) + "\n" + cur + "}"
    return json_escape_string(str(v), ensure_ascii)


def colorize_json_text(s: str) -> str:
    # A lightweight colorizer approximating jq -C.  It colorizes strings,
    # numbers/literals, and punctuation sufficiently for terminal-visible tests.
    out=[]; i=0; n=len(s)
    while i<n:
        c=s[i]
        if c=='"':
            j=i+1; esc=False
            while j<n:
                ch=s[j]
                if esc: esc=False
                elif ch=='\\': esc=True
                elif ch=='"': j+=1; break
                j+=1
            out.append('\033[0;32m'+s[i:j]+'\033[0m'); i=j
        elif c in '{}[]:,':
            out.append('\033[1;39m'+c+'\033[0m'); i+=1
        elif s.startswith('null', i):
            out.append('\033[0;90mnull\033[0m'); i+=4
        elif s.startswith('true', i):
            out.append('\033[0;39mtrue\033[0m'); i+=4
        elif s.startswith('false', i):
            out.append('\033[0;39mfalse\033[0m'); i+=5
        elif c=='-' or c.isdigit():
            j=i+1
            while j<n and (s[j].isdigit() or s[j] in '.eE+-'):
                j+=1
            out.append('\033[0;39m'+s[i:j]+'\033[0m'); i=j
        else:
            out.append(c); i+=1
    return ''.join(out)


def short_json(v):
    try:
        s = dump_json(v, compact=True, ensure_ascii=False)
    except Exception:
        s = repr(v)
    if len(s) > 20:
        if s.startswith('"'):
            return s[:18] + '..."'
        return s[:18] + '...'
    return s

# ---------------------------- Lexer ----------------------------

@dataclass
class Token:
    typ: str
    val: Any
    pos: int

KEYWORDS = {"if","then","else","elif","end","as","reduce","foreach","try","catch","def","and","or","label","break"}
MULTI_OPS = ["//=" , "|=", "+=", "-=", "*=", "/=", "%=", "==", "!=", "<=", ">=", "//"]
SINGLE = set("()[]{}:;,|+-*/%=<>.?$")

class Lexer:
    def __init__(self, src: str):
        self.src = src
        self.i = 0
        self.n = len(src)
    def peek(self):
        return self.src[self.i] if self.i < self.n else ''
    def next_tokens(self):
        toks=[]
        while self.i < self.n:
            c=self.src[self.i]
            if c.isspace():
                self.i+=1; continue
            if c=='#':
                while self.i<self.n and self.src[self.i] not in '\r\n': self.i+=1
                continue
            pos=self.i
            if c=='"':
                toks.append(Token('STRING', self.scan_string(), pos)); continue
            if c=='@':
                self.i+=1
                m=re.match(r'[A-Za-z0-9_]+', self.src[self.i:])
                if not m: raise JQCompileError("syntax error, unexpected FORMAT")
                val=m.group(0); self.i+=len(val)
                toks.append(Token('FORMAT', val, pos)); continue
            if c=='$':
                self.i+=1
                m=re.match(r'[A-Za-z_][A-Za-z0-9_]*', self.src[self.i:])
                if not m: raise JQCompileError("syntax error, unexpected '$'")
                val=m.group(0); self.i+=len(val)
                toks.append(Token('VAR', val, pos)); continue
            # numbers: JSON-like, but a '-' followed by digit belongs to number
            if c.isdigit() or (c=='-' and self.i+1<self.n and self.src[self.i+1].isdigit()):
                j=self.i
                if self.src[j]=='-': j+=1
                if j<self.n and self.src[j]=='0': j+=1
                else:
                    while j<self.n and self.src[j].isdigit(): j+=1
                if j<self.n and self.src[j]=='.':
                    j+=1
                    while j<self.n and self.src[j].isdigit(): j+=1
                if j<self.n and self.src[j] in 'eE':
                    j+=1
                    if j<self.n and self.src[j] in '+-': j+=1
                    while j<self.n and self.src[j].isdigit(): j+=1
                raw=self.src[self.i:j]
                self.i=j
                toks.append(Token('NUMBER', JQNumber(raw), pos)); continue
            if c.isalpha() or c=='_':
                m=re.match(r'[A-Za-z_][A-Za-z0-9_]*', self.src[self.i:])
                val=m.group(0); self.i+=len(val)
                if val in KEYWORDS:
                    toks.append(Token(val.upper(), val, pos))
                else:
                    toks.append(Token('ID', val, pos))
                continue
            matched=False
            for op in MULTI_OPS:
                if self.src.startswith(op, self.i):
                    toks.append(Token('OP', op, pos)); self.i+=len(op); matched=True; break
            if matched: continue
            if c in SINGLE:
                self.i+=1
                toks.append(Token(c, c, pos)); continue
            raise JQCompileError(f"syntax error, unexpected {c!r}")
        toks.append(Token('EOF','EOF',self.n))
        return toks

    def scan_string(self):
        # Returns either a Python string or [('text', str), ('expr', source), ...]
        assert self.src[self.i]=='"'
        self.i += 1
        raw_parts=[]
        cur=[]
        has_interp=False
        esc=False
        while self.i < self.n:
            c=self.src[self.i]
            if esc:
                # interpolation begins with \( (not a JSON escape)
                if c=='(':
                    has_interp=True
                    if cur:
                        raw_parts.append(('text_raw', ''.join(cur))); cur=[]
                    self.i += 1
                    start=self.i
                    depth=1
                    in_str=False; str_esc=False
                    while self.i < self.n and depth>0:
                        ch=self.src[self.i]
                        if in_str:
                            if str_esc: str_esc=False
                            elif ch=='\\': str_esc=True
                            elif ch=='"': in_str=False
                        else:
                            if ch=='"': in_str=True
                            elif ch=='(':
                                depth+=1
                            elif ch==')':
                                depth-=1
                                if depth==0: break
                        self.i += 1
                    if depth != 0:
                        raise JQCompileError("syntax error, unterminated string interpolation")
                    expr=self.src[start:self.i]
                    raw_parts.append(('expr', expr))
                    self.i += 1
                    esc=False
                    continue
                else:
                    cur.append('\\'); cur.append(c); self.i += 1; esc=False; continue
            if c=='\\':
                esc=True; self.i += 1; continue
            if c=='"':
                self.i += 1
                if not has_interp:
                    raw=''.join(cur)
                    try:
                        return json.loads('"'+raw+'"')
                    except Exception:
                        # fall back to unicode_escape-like behavior
                        return bytes(raw, 'utf-8').decode('unicode_escape')
                if cur:
                    raw_parts.append(('text_raw',''.join(cur)))
                parts=[]
                for typ,val in raw_parts:
                    if typ=='expr':
                        parts.append(('expr', val))
                    else:
                        try: txt=json.loads('"'+val+'"')
                        except Exception: txt=val
                        parts.append(('text', txt))
                return parts
            cur.append(c); self.i += 1
        raise JQCompileError("syntax error, unterminated string")

# ---------------------------- AST Nodes ----------------------------

class Node:
    def eval(self, ctx, inp):
        raise NotImplementedError
    def paths(self, ctx, root):
        raise JQError("Invalid path expression")

class Identity(Node):
    def eval(self, ctx, inp):
        yield inp
    def paths(self, ctx, root):
        return [[]]

class Literal(Node):
    def __init__(self, val): self.val=val
    def eval(self, ctx, inp):
        yield deepcopy_jq(self.val)

class EmptyNode(Node):
    def eval(self, ctx, inp):
        if False: yield None

class Var(Node):
    def __init__(self, name): self.name=name
    def eval(self, ctx, inp):
        if self.name in ctx.vars:
            yield deepcopy_jq(ctx.vars[self.name])
        else:
            raise JQError(f"${self.name} is not defined")

class Pipe(Node):
    def __init__(self,l,r): self.l=l; self.r=r
    def eval(self, ctx, inp):
        for v in self.l.eval(ctx, inp):
            yield from self.r.eval(ctx, v)

class Comma(Node):
    def __init__(self,l,r): self.l=l; self.r=r
    def eval(self, ctx, inp):
        yield from self.l.eval(ctx, inp)
        yield from self.r.eval(ctx, inp)
    def paths(self, ctx, root):
        return self.l.paths(ctx, root) + self.r.paths(ctx, root)

class Paren(Node):
    def __init__(self,n): self.n=n
    def eval(self, ctx, inp): yield from self.n.eval(ctx, inp)
    def paths(self, ctx, root): return self.n.paths(ctx, root)

class OptionalNode(Node):
    def __init__(self,n): self.n=n
    def eval(self, ctx, inp):
        try:
            yield from self.n.eval(ctx, inp)
        except JQError:
            return
    def paths(self, ctx, root):
        try: return self.n.paths(ctx, root)
        except JQError: return []

class Index(Node):
    def __init__(self, base, key_node=None, is_iter=False, is_slice=False, end_node=None):
        self.base=base; self.key_node=key_node; self.is_iter=is_iter; self.is_slice=is_slice; self.end_node=end_node
    def eval(self, ctx, inp):
        for basev in self.base.eval(ctx, inp):
            if self.is_iter:
                if isinstance(basev, list):
                    for x in basev: yield x
                elif isinstance(basev, dict):
                    for x in basev.values(): yield x
                else:
                    raise JQError(f"Cannot iterate over {type_name(basev)} ({short_json(basev)})")
            elif self.is_slice:
                starts = [None] if self.key_node is None else list(self.key_node.eval(ctx, basev))
                ends = [None] if self.end_node is None else list(self.end_node.eval(ctx, basev))
                for st in starts:
                    for en in ends:
                        yield jq_slice(basev, st, en)
            else:
                keys=list(self.key_node.eval(ctx, basev))
                for k in keys:
                    yield jq_index(basev, k)
    def paths(self, ctx, root):
        out=[]
        for p in self.base.paths(ctx, root):
            target=get_path(root, p, missing_none=True)
            if self.is_iter:
                if isinstance(target, list):
                    out.extend([p+[i] for i in range(len(target))])
                elif isinstance(target, dict):
                    out.extend([p+[k] for k in target.keys()])
                elif target is None:
                    pass
                else:
                    raise JQError(f"Cannot iterate over {type_name(target)} ({short_json(target)})")
            elif self.is_slice:
                raise JQError("Invalid path expression with slice")
            else:
                if isinstance(self.key_node, Literal):
                    keys=[self.key_node.val]
                else:
                    keys=list(self.key_node.eval(ctx, target))
                for k in keys:
                    if isinstance(k, JQNumber):
                        k=int(k.dec)
                    out.append(p+[k])
        return out

class ArrayConstruct(Node):
    def __init__(self, expr): self.expr=expr
    def eval(self, ctx, inp):
        arr=[]
        for v in self.expr.eval(ctx, inp): arr.append(v)
        yield arr

class ObjectConstruct(Node):
    def __init__(self, entries): self.entries=entries  # list (keynode,valueNode)
    def eval(self, ctx, inp):
        def rec(i, obj):
            if i>=len(self.entries):
                yield obj; return
            keynode, valnode = self.entries[i]
            keyouts=list(keynode.eval(ctx, inp))
            valouts=list(valnode.eval(ctx, inp))
            if not keyouts or not valouts:
                return
            for k in keyouts:
                if not isinstance(k, str):
                    raise JQError(f"Cannot use {type_name(k)} ({short_json(k)}) as object key")
                for v in valouts:
                    no=OrderedDict(obj)
                    no[k]=v
                    yield from rec(i+1, no)
        yield from rec(0, OrderedDict())

class Unary(Node):
    def __init__(self, op, n): self.op=op; self.n=n
    def eval(self, ctx, inp):
        for v in self.n.eval(ctx, inp):
            if self.op=='-':
                if isinstance(v, JQNumber): yield JQNumber(-v.dec)
                else: raise JQError(f"{type_name(v)} ({short_json(v)}) cannot be negated")
            else:
                yield v

class Binary(Node):
    def __init__(self, op, l, r): self.op=op; self.l=l; self.r=r
    def eval(self, ctx, inp):
        if self.op=='//':
            good=[]
            for v in self.l.eval(ctx, inp):
                if jq_truth(v): good.append(v)
            if good:
                for v in good: yield v
            else:
                yield from self.r.eval(ctx, inp)
            return
        # jq evaluates binary operands against the same input and forms products.
        lvals=list(self.l.eval(ctx, inp))
        if not lvals: return
        rvals=list(self.r.eval(ctx, inp))
        if not rvals: return
        for a in lvals:
            for b in rvals:
                if self.op in ('and','or'):
                    yield (jq_truth(a) and jq_truth(b)) if self.op=='and' else (jq_truth(a) or jq_truth(b))
                elif self.op in ('==','!=','<','>','<=','>='):
                    cmp = jq_compare(a,b)
                    if self.op=='==': yield jq_equal(a,b)
                    elif self.op=='!=': yield not jq_equal(a,b)
                    elif self.op=='<': yield cmp < 0
                    elif self.op=='>': yield cmp > 0
                    elif self.op=='<=': yield cmp <= 0
                    elif self.op=='>=': yield cmp >= 0
                else:
                    yield jq_binop(self.op, a, b)

class IfNode(Node):
    def __init__(self, cond, thenn, elsen): self.cond=cond; self.thenn=thenn; self.elsen=elsen
    def eval(self, ctx, inp):
        for c in self.cond.eval(ctx, inp):
            if jq_truth(c): yield from self.thenn.eval(ctx, inp)
            else: yield from self.elsen.eval(ctx, inp)

class AsNode(Node):
    def __init__(self, expr, var, body): self.expr=expr; self.var=var; self.body=body
    def eval(self, ctx, inp):
        for v in self.expr.eval(ctx, inp):
            nctx=ctx.with_var(self.var, v)
            yield from self.body.eval(nctx, inp)

class ReduceNode(Node):
    def __init__(self, gen, var, init, update): self.gen=gen; self.var=var; self.init=init; self.update=update
    def eval(self, ctx, inp):
        states=list(self.init.eval(ctx, inp))
        if not states: return
        acc=states[0]
        for item in self.gen.eval(ctx, inp):
            nctx=ctx.with_var(self.var, item)
            outs=list(self.update.eval(nctx, acc))
            if not outs: return
            acc=outs[0]
        yield acc

class TryNode(Node):
    def __init__(self, body, handler=None): self.body=body; self.handler=handler
    def eval(self, ctx, inp):
        try:
            yield from self.body.eval(ctx, inp)
        except JQError as e:
            if self.handler is None:
                return
            nctx=ctx.with_var('__jq_error__', str(e))
            yield from self.handler.eval(nctx, inp)

class Assignment(Node):
    def __init__(self, pathnode, op, rhs): self.pathnode=pathnode; self.op=op; self.rhs=rhs
    def eval(self, ctx, inp):
        paths=self.pathnode.paths(ctx, inp)
        if self.op=='=':
            for rv in self.rhs.eval(ctx, inp):
                root=deepcopy_jq(inp)
                for p in paths:
                    root=set_path(root, p, deepcopy_jq(rv))
                yield root
        elif self.op=='|=':
            root=deepcopy_jq(inp)
            for p in paths:
                old=get_path(root, p, missing_none=True)
                outs=list(self.rhs.eval(ctx, old))
                if not outs:
                    root=del_path(root, p)
                else:
                    root=set_path(root, p, outs[0])
            yield root
        elif self.op in ('+=','-=','*=','/=','%=','//='):
            # RHS is evaluated once for each path against the original input.
            root=deepcopy_jq(inp)
            for p in paths:
                old=get_path(root, p, missing_none=True)
                if self.op=='//=':
                    if jq_truth(old):
                        continue
                    outs=list(self.rhs.eval(ctx, inp))
                    if outs: root=set_path(root, p, outs[0])
                else:
                    outs=list(self.rhs.eval(ctx, inp))
                    if not outs: continue
                    op=self.op[0]
                    root=set_path(root, p, jq_binop(op, old, outs[0]))
            yield root

class StringInterp(Node):
    def __init__(self, parts, parser_factory):
        self.parts=[]
        for typ,val in parts:
            if typ=='text': self.parts.append(('text', val))
            else: self.parts.append(('expr', parser_factory(val)))
    def eval(self, ctx, inp):
        # Cartesian product over interpolation expressions.
        acc=['']
        for typ,val in self.parts:
            if typ=='text':
                acc=[s+val for s in acc]
            else:
                outs=list(val.eval(ctx, inp))
                strs=[jq_tostring(x) for x in outs]
                acc=[s+t for s in acc for t in strs]
        for s in acc: yield s

class FormatNode(Node):
    def __init__(self, fmt): self.fmt=fmt
    def eval(self, ctx, inp):
        yield format_value(self.fmt, inp)

class FuncCall(Node):
    def __init__(self, name, args=None): self.name=name; self.args=args or []
    def eval(self, ctx, inp):
        yield from eval_func(self.name, self.args, ctx, inp)

# ---------------------------- jq operations ----------------------------

def jq_index(v, k):
    if isinstance(k, JQNumber):
        # numeric index
        idx=int(k.dec)
        if v is None: return None
        if isinstance(v, list):
            if idx < 0: idx += len(v)
            if 0 <= idx < len(v): return v[idx]
            return None
        if isinstance(v, dict): raise JQError("Cannot index object with number")
        if isinstance(v, str): raise JQError("Cannot index string with number")
        raise JQError(f"Cannot index {type_name(v)} with number")
    if isinstance(k, str):
        if v is None: return None
        if isinstance(v, dict): return v.get(k, None)
        if isinstance(v, list): raise JQError(f"Cannot index array with string {json_escape_string(k)}")
        if isinstance(v, str): raise JQError(f"Cannot index string with string {json_escape_string(k)}")
        raise JQError(f"Cannot index {type_name(v)} with string {json_escape_string(k)}")
    raise JQError(f"Cannot index {type_name(v)} with {type_name(k)}")


def to_int_or_none(x):
    if x is None: return None
    if isinstance(x, JQNumber): return int(x.dec)
    raise JQError(f"Start and end indices of an array slice must be numbers")


def jq_slice(v, st, en):
    if v is None: return None
    a=to_int_or_none(st); b=to_int_or_none(en)
    if isinstance(v, list) or isinstance(v, str):
        return v[slice(a,b)]
    raise JQError(f"Cannot index {type_name(v)} with object")


def jq_binop(op,a,b):
    if op=='+': return jq_add(a,b)
    if op=='-': return jq_sub(a,b)
    if op=='*': return jq_mul(a,b)
    if op=='/': return jq_div(a,b)
    if op=='%': return jq_mod(a,b)
    raise JQError(f"unknown operator {op}")


def jq_add(a,b):
    if a is None: return deepcopy_jq(b)
    if b is None: return deepcopy_jq(a)
    if isinstance(a,JQNumber) and isinstance(b,JQNumber): return JQNumber(a.dec+b.dec)
    if isinstance(a,str) and isinstance(b,str): return a+b
    if isinstance(a,list) and isinstance(b,list): return deepcopy_jq(a)+deepcopy_jq(b)
    if isinstance(a,dict) and isinstance(b,dict):
        o=OrderedDict((k,deepcopy_jq(v)) for k,v in a.items())
        for k,v in b.items(): o[k]=deepcopy_jq(v)
        return o
    raise JQError(f"{type_name(a)} ({short_json(a)}) and {type_name(b)} ({short_json(b)}) cannot be added")

def jq_sub(a,b):
    if isinstance(a,JQNumber) and isinstance(b,JQNumber): return JQNumber(a.dec-b.dec)
    if isinstance(a,list) and isinstance(b,list):
        return [x for x in a if not any(jq_equal(x,y) for y in b)]
    raise JQError(f"{type_name(a)} ({short_json(a)}) and {type_name(b)} ({short_json(b)}) cannot be subtracted")

def recursive_merge(a,b):
    o=OrderedDict((k,deepcopy_jq(v)) for k,v in a.items())
    for k,v in b.items():
        if k in o and isinstance(o[k],dict) and isinstance(v,dict): o[k]=recursive_merge(o[k],v)
        else: o[k]=deepcopy_jq(v)
    return o

def jq_mul(a,b):
    if isinstance(a,JQNumber) and isinstance(b,JQNumber): return JQNumber(a.dec*b.dec)
    if isinstance(a,str) and isinstance(b,JQNumber): return a*max(0,int(b.dec))
    if isinstance(a,JQNumber) and isinstance(b,str): return b*max(0,int(a.dec))
    if isinstance(a,dict) and isinstance(b,dict): return recursive_merge(a,b)
    raise JQError(f"{type_name(a)} ({short_json(a)}) and {type_name(b)} ({short_json(b)}) cannot be multiplied")

def jq_div(a,b):
    if isinstance(a,JQNumber) and isinstance(b,JQNumber):
        if b.dec == 0: raise JQError(f"number ({a.raw}) and number ({b.raw}) cannot be divided because the divisor is zero")
        return JQNumber(a.dec/b.dec)
    if isinstance(a,str) and isinstance(b,str): return a.split(b)
    raise JQError(f"{type_name(a)} ({short_json(a)}) and {type_name(b)} ({short_json(b)}) cannot be divided")

def jq_mod(a,b):
    if isinstance(a,JQNumber) and isinstance(b,JQNumber):
        if b.dec == 0: raise JQError(f"number ({a.raw}) and number ({b.raw}) cannot be divided (remainder) because the divisor is zero")
        return JQNumber(a.dec % b.dec)
    raise JQError(f"{type_name(a)} ({short_json(a)}) and {type_name(b)} ({short_json(b)}) cannot be divided (remainder)")


def jq_equal(a,b):
    if isinstance(a,JQNumber) and isinstance(b,JQNumber): return a.dec == b.dec
    if type(a) != type(b):
        # bool is not number here because JQNumber is separate.
        return False
    if isinstance(a,list): return len(a)==len(b) and all(jq_equal(x,y) for x,y in zip(a,b))
    if isinstance(a,dict):
        return set(a.keys())==set(b.keys()) and all(jq_equal(a[k],b[k]) for k in a.keys())
    return a==b


def rank(v):
    if v is None: return 0
    if v is False: return 1
    if v is True: return 2
    if isinstance(v,JQNumber): return 3
    if isinstance(v,str): return 4
    if isinstance(v,list): return 5
    if isinstance(v,dict): return 6
    return 7


def jq_compare(a,b):
    if jq_equal(a,b): return 0
    ra,rb=rank(a),rank(b)
    if ra!=rb: return -1 if ra<rb else 1
    if isinstance(a,JQNumber): return -1 if a.dec < b.dec else 1
    if isinstance(a,str): return -1 if a < b else 1
    if isinstance(a,list):
        for x,y in zip(a,b):
            c=jq_compare(x,y)
            if c: return c
        return -1 if len(a)<len(b) else 1
    if isinstance(a,dict):
        ak=sorted(a.keys()); bk=sorted(b.keys())
        if ak!=bk: return -1 if ak<bk else 1
        for k in ak:
            c=jq_compare(a[k],b[k])
            if c: return c
        return 0
    return -1 if str(a)<str(b) else 1


def sort_key(v):
    return Sortable(v)
class Sortable:
    def __init__(self,v): self.v=v
    def __lt__(self,o): return jq_compare(self.v,o.v)<0
    def __eq__(self,o): return jq_equal(self.v,o.v)


def jq_tostring(v):
    if isinstance(v, str): return v
    return dump_json(v, compact=True, ensure_ascii=False)

# ---------------------------- paths/update helpers ----------------------------

def get_path(root, path, missing_none=False):
    cur=root
    for p in path:
        try:
            if isinstance(cur, dict) and isinstance(p,str): cur=cur[p]
            elif isinstance(cur, list) and isinstance(p,int):
                idx=p if p>=0 else len(cur)+p
                if idx<0 or idx>=len(cur):
                    if missing_none: return None
                    raise KeyError
                cur=cur[idx]
            else:
                if missing_none: return None
                raise KeyError
        except KeyError:
            if missing_none: return None
            raise
    return cur


def container_for_next(nextkey):
    return [] if isinstance(nextkey,int) else OrderedDict()


def set_path(root, path, val):
    if not path: return deepcopy_jq(val)
    if root is None or not isinstance(root,(dict,list)):
        root = container_for_next(path[0])
    cur=root
    for i,p in enumerate(path[:-1]):
        nxt=path[i+1]
        if isinstance(p,JQNumber): p=int(p.dec)
        if isinstance(p,int):
            if not isinstance(cur,list): raise JQError("Cannot index object with number")
            while len(cur)<=p: cur.append(None)
            if cur[p] is None or not isinstance(cur[p],(dict,list)):
                cur[p]=container_for_next(nxt)
            cur=cur[p]
        else:
            if not isinstance(cur,dict): raise JQError(f"Cannot index array with string {json_escape_string(str(p))}")
            if p not in cur or cur[p] is None or not isinstance(cur[p],(dict,list)):
                cur[p]=container_for_next(nxt)
            cur=cur[p]
    last=path[-1]
    if isinstance(last,JQNumber): last=int(last.dec)
    if isinstance(last,int):
        if not isinstance(cur,list): raise JQError("Cannot index object with number")
        idx=last
        if idx<0: idx+=len(cur)
        if idx<0: idx=0
        while len(cur)<=idx: cur.append(None)
        cur[idx]=deepcopy_jq(val)
    else:
        if not isinstance(cur,dict): raise JQError(f"Cannot index array with string {json_escape_string(str(last))}")
        cur[str(last)]=deepcopy_jq(val)
    return root


def del_path(root, path):
    if not path: return None
    root=deepcopy_jq(root)
    cur=root
    for p in path[:-1]:
        if isinstance(cur,dict) and isinstance(p,str): cur=cur.get(p)
        elif isinstance(cur,list) and isinstance(p,int) and 0<=p<len(cur): cur=cur[p]
        else: return root
    last=path[-1]
    if isinstance(cur,dict) and isinstance(last,str): cur.pop(last,None)
    elif isinstance(cur,list) and isinstance(last,int):
        idx=last if last>=0 else len(cur)+last
        if 0<=idx<len(cur): del cur[idx]
    return root

# ---------------------------- Parser ----------------------------

class Parser:
    def __init__(self, src: str):
        self.src=src
        self.toks=Lexer(src).next_tokens()
        self.i=0
    def cur(self): return self.toks[self.i]
    def val(self): return self.cur().val
    def typ(self): return self.cur().typ
    def at_stop(self, stops):
        if self.typ()=='EOF': return True
        return self.val() in stops or self.typ() in stops
    def accept(self, val_or_typ):
        if self.val()==val_or_typ or self.typ()==val_or_typ:
            t=self.cur(); self.i+=1; return t
        return None
    def expect(self, val_or_typ):
        t=self.accept(val_or_typ)
        if not t:
            raise JQCompileError(f"syntax error, unexpected {self.val()}")
        return t
    def peek_next_val(self):
        return self.toks[self.i+1].val if self.i+1<len(self.toks) else None

    def parse(self):
        # Skip simple def declarations by recording no-arg functions in context?  For
        # now, parse and store locally on Program node by expanding calls via ctx.funcs.
        defs={}
        while self.typ()=='DEF':
            self.i+=1
            name=self.expect('ID').val
            params=[]
            if self.accept('('):
                if not self.accept(')'):
                    while True:
                        params.append(self.expect('ID').val)
                        if self.accept(';') or self.accept(','): continue
                        self.expect(')'); break
            self.expect(':')
            body=self.parse_expr(stops={';'})
            self.expect(';')
            defs[name]=(params,body)
        if self.typ()=='EOF':
            raise JQCompileError('Top-level program not given (try ".")')
        expr=self.parse_expr(stops={'EOF'})
        if self.typ()!='EOF':
            raise JQCompileError(f"syntax error, unexpected {self.val()}")
        if defs:
            return DefProgram(defs, expr)
        return expr

    def parse_expr(self, stops=set()):
        return self.parse_pipe(stops)

    def parse_pipe(self, stops):
        left=self.parse_comma(stops | {'|'})
        if self.typ()=='AS':
            self.i+=1
            var=self.expect('VAR').val
            self.expect('|')
            body=self.parse_pipe(stops)
            return AsNode(left,var,body)
        while self.accept('|'):
            right=self.parse_pipe(stops)
            left=Pipe(left,right)
            if self.at_stop(stops): break
        return left

    def parse_comma(self, stops):
        left=self.parse_assign(stops | {','})
        while not self.at_stop(stops) and self.accept(','):
            right=self.parse_assign(stops | {','})
            left=Comma(left,right)
        return left

    def parse_assign(self, stops):
        left=self.parse_alt(stops)
        if self.typ()=='OP' and self.val() in ('|=','+=','-=','*=','/=','%=','//='):
            op=self.val(); self.i+=1
            rhs=self.parse_alt(stops)
            return Assignment(left,op,rhs)
        if self.accept('='):
            rhs=self.parse_alt(stops)
            return Assignment(left,'=',rhs)
        return left

    def parse_alt(self, stops):
        left=self.parse_or(stops)
        while self.typ()=='OP' and self.val()=='//':
            self.i+=1
            right=self.parse_alt(stops)
            left=Binary('//',left,right)
        return left

    def parse_or(self, stops):
        left=self.parse_and(stops)
        while self.typ()=='OR':
            self.i+=1; right=self.parse_and(stops); left=Binary('or',left,right)
        return left

    def parse_and(self, stops):
        left=self.parse_compare(stops)
        while self.typ()=='AND':
            self.i+=1; right=self.parse_compare(stops); left=Binary('and',left,right)
        return left

    def parse_compare(self, stops):
        left=self.parse_add(stops)
        while (self.typ()=='OP' and self.val() in ('==','!=','<=','>=')) or self.val() in ('<','>'):
            op=self.val(); self.i+=1
            right=self.parse_add(stops)
            left=Binary(op,left,right)
        return left

    def parse_add(self, stops):
        left=self.parse_mul(stops)
        while self.val() in ('+','-') and not self.at_stop(stops):
            op=self.val(); self.i+=1
            right=self.parse_mul(stops)
            left=Binary(op,left,right)
        return left

    def parse_mul(self, stops):
        left=self.parse_unary(stops)
        while self.val() in ('*','/','%') and not self.at_stop(stops):
            op=self.val(); self.i+=1
            right=self.parse_unary(stops)
            left=Binary(op,left,right)
        return left

    def parse_unary(self, stops):
        if self.accept('-'):
            return Unary('-', self.parse_unary(stops))
        return self.parse_postfix(stops)

    def parse_postfix(self, stops):
        node=self.parse_primary(stops)
        while not self.at_stop(stops):
            if self.accept('?'):
                node=OptionalNode(node); continue
            if self.accept('.'):
                node=self.parse_after_dot(node, stops)
                continue
            if self.accept('['):
                node=self.parse_bracket_suffix(node, stops)
                continue
            break
        return node

    def parse_after_dot(self, base, stops):
        if self.typ()=='ID':
            key=self.cur().val; self.i+=1
            return Index(base, Literal(key))
        if self.typ()=='STRING' and isinstance(self.cur().val,str):
            key=self.cur().val; self.i+=1
            return Index(base, Literal(key))
        if self.accept('['):
            return self.parse_bracket_suffix(base, stops)
        # A bare dot already consumed after an expression is identity pipe-ish; reject softly.
        raise JQCompileError(f"syntax error, unexpected {self.val()}")

    def parse_bracket_suffix(self, base, stops):
        if self.accept(']'):
            return Index(base, is_iter=True)
        # slice starts with ':'
        if self.accept(':'):
            end=None if self.val()==']' else self.parse_expr(stops={']'})
            self.expect(']')
            return Index(base, None, is_slice=True, end_node=end)
        first=self.parse_expr(stops={']',':'})
        if self.accept(':'):
            end=None if self.val()==']' else self.parse_expr(stops={']'})
            self.expect(']')
            return Index(base, first, is_slice=True, end_node=end)
        self.expect(']')
        return Index(base, first)

    def parse_primary(self, stops):
        t=self.cur()
        if self.at_stop(stops):
            raise JQCompileError("syntax error, unexpected end of file")
        if self.accept('.'):
            node=Identity()
            # initial .foo / .[] / .[x]
            if self.typ()=='ID':
                key=self.cur().val; self.i+=1; node=Index(node, Literal(key))
            elif self.typ()=='STRING' and isinstance(self.cur().val,str):
                key=self.cur().val; self.i+=1; node=Index(node, Literal(key))
            elif self.accept('['):
                node=self.parse_bracket_suffix(node, stops)
            return node
        if t.typ=='NUMBER': self.i+=1; return Literal(t.val)
        if t.typ=='STRING':
            self.i+=1
            if isinstance(t.val, list):
                return StringInterp(t.val, lambda s: Parser(s).parse())
            return Literal(t.val)
        if t.typ=='VAR': self.i+=1; return Var(t.val)
        if t.typ=='FORMAT': self.i+=1; return FormatNode(t.val)
        if self.accept('('):
            e=self.parse_expr(stops={')'})
            self.expect(')')
            return Paren(e)
        if self.accept('['):
            if self.accept(']'):
                return Literal([])
            e=self.parse_expr(stops={']'})
            self.expect(']')
            return ArrayConstruct(e)
        if self.accept('{'):
            return self.parse_object()
        if t.typ=='IF':
            return self.parse_if()
        if t.typ=='REDUCE':
            return self.parse_reduce()
        if t.typ=='TRY':
            self.i+=1
            body=self.parse_expr(stops={'CATCH','catch'} | set(stops))
            handler=None
            if self.typ()=='CATCH':
                self.i+=1
                handler=self.parse_expr(stops=stops)
            return TryNode(body, handler)
        if t.typ=='BREAK':
            self.i+=1
            return FuncCall('break', [])
        if t.typ=='ID':
            name=t.val; self.i+=1
            if name=='null': return Literal(None)
            if name=='true': return Literal(True)
            if name=='false': return Literal(False)
            if name=='empty': return EmptyNode()
            args=[]
            if self.accept('('):
                if not self.accept(')'):
                    while True:
                        args.append(self.parse_expr(stops={';',')'}))
                        if self.accept(';'):
                            continue
                        self.expect(')'); break
            return FuncCall(name,args)
        raise JQCompileError(f"syntax error, unexpected {t.val}")

    def parse_if(self):
        self.expect('IF')
        cond=self.parse_expr(stops={'THEN'})
        self.expect('THEN')
        thenn=self.parse_expr(stops={'ELSE','ELIF','END'})
        if self.typ()=='ELIF':
            # elif c then t else e end == else if c then t else e end
            self.i+=1
            cond2=self.parse_expr(stops={'THEN'})
            self.expect('THEN')
            then2=self.parse_expr(stops={'ELSE','ELIF','END'})
            if self.typ()=='ELSE':
                self.i+=1; else2=self.parse_expr(stops={'END'}); self.expect('END')
            else:
                self.expect('END'); else2=Literal(None)
            elsen=IfNode(cond2, then2, else2)
        elif self.typ()=='ELSE':
            self.i+=1
            elsen=self.parse_expr(stops={'END'})
            self.expect('END')
        else:
            self.expect('END')
            elsen=Literal(None)
        return IfNode(cond, thenn, elsen)

    def parse_reduce(self):
        self.expect('REDUCE')
        gen=self.parse_expr(stops={'AS'})
        self.expect('AS')
        var=self.expect('VAR').val
        self.expect('(')
        init=self.parse_expr(stops={';'})
        self.expect(';')
        update=self.parse_expr(stops={')'})
        self.expect(')')
        return ReduceNode(gen,var,init,update)

    def parse_object(self):
        entries=[]
        if self.accept('}'):
            return Literal(OrderedDict())
        while True:
            # key and value
            if self.accept('('):
                keynode=self.parse_expr(stops={')'})
                self.expect(')'); self.expect(':')
                valnode=self.parse_expr(stops={',','}'})
            elif self.typ()=='STRING' and isinstance(self.cur().val,str):
                s=self.cur().val; self.i+=1
                if self.accept(':'):
                    keynode=Literal(s); valnode=self.parse_expr(stops={',','}'})
                else:
                    keynode=Literal(s); valnode=Index(Identity(), Literal(s))
            elif self.typ()=='ID':
                s=self.cur().val; self.i+=1
                if self.accept(':'):
                    keynode=Literal(s); valnode=self.parse_expr(stops={',','}'})
                else:
                    keynode=Literal(s); valnode=Index(Identity(), Literal(s))
            else:
                keynode=self.parse_expr(stops={':'})
                self.expect(':')
                valnode=self.parse_expr(stops={',','}'})
            entries.append((keynode,valnode))
            if self.accept(','):
                if self.accept('}'):
                    break
                continue
            self.expect('}')
            break
        return ObjectConstruct(entries)

class DefProgram(Node):
    def __init__(self, defs, expr): self.defs=defs; self.expr=expr
    def eval(self, ctx, inp):
        old=ctx.funcs.copy(); ctx.funcs.update(self.defs)
        try:
            yield from self.expr.eval(ctx, inp)
        finally:
            ctx.funcs=old

# ---------------------------- builtins ----------------------------

class Context:
    def __init__(self, vars=None, inputs=None, funcs=None, opts=None):
        self.vars=vars or {}
        self.inputs=inputs
        self.funcs=funcs or {}
        self.opts=opts or {}
    def with_var(self, name, value):
        nv=self.vars.copy(); nv[name]=deepcopy_jq(value)
        return Context(nv,self.inputs,self.funcs,self.opts)

class InputStream:
    def __init__(self, vals): self.vals=vals; self.index=0
    def next(self):
        if self.index >= len(self.vals): raise JQError("break")
        v=self.vals[self.index]; self.index+=1; return v
    def rest(self):
        while self.index < len(self.vals):
            v=self.vals[self.index]; self.index+=1; yield v


def first_arg_value(arg, ctx, inp, default=None):
    if arg is None: return default
    for v in arg.eval(ctx, inp): return v
    return default

def all_arg_values(arg, ctx, inp):
    return list(arg.eval(ctx, inp))


def eval_func(name, args, ctx, inp):
    # User defs: no-arg defs or simple value-argument defs.
    if name in ctx.funcs:
        params, body = ctx.funcs[name]
        nctx=ctx
        for p,arg in zip(params,args):
            val=first_arg_value(arg, ctx, inp, None)
            nctx=nctx.with_var(p, val)
        yield from body.eval(nctx, inp); return

    if name=='not': yield (not jq_truth(inp)); return
    if name=='length': yield builtin_length(inp); return
    if name=='type': yield jq_type_string(inp); return
    if name=='keys': yield builtin_keys(inp, True); return
    if name=='keys_unsorted': yield builtin_keys(inp, False); return
    if name=='values':
        if inp is not None: yield inp
        return
    if name in ('scalars','arrays','objects','iterables','booleans','numbers','strings','nulls'):
        ok=False
        if name=='scalars': ok=not isinstance(inp,(list,dict))
        elif name=='arrays': ok=isinstance(inp,list)
        elif name=='objects': ok=isinstance(inp,dict)
        elif name=='iterables': ok=isinstance(inp,(list,dict))
        elif name=='booleans': ok=isinstance(inp,bool)
        elif name=='numbers': ok=isinstance(inp,JQNumber)
        elif name=='strings': ok=isinstance(inp,str)
        elif name=='nulls': ok=inp is None
        if ok: yield inp
        return
    if name=='has':
        key=first_arg_value(args[0] if args else None, ctx, inp)
        yield builtin_has(inp,key); return
    if name=='in':
        obj=first_arg_value(args[0] if args else None, ctx, inp)
        yield builtin_has(obj,inp); return
    if name=='map':
        if not args: raise JQError('map requires an argument')
        if isinstance(inp,list):
            arr=[]
            for x in inp:
                arr.extend(args[0].eval(ctx,x))
            yield arr
        elif isinstance(inp,dict):
            arr=[]
            for x in inp.values(): arr.extend(args[0].eval(ctx,x))
            yield arr
        else: raise JQError(f"Cannot iterate over {type_name(inp)} ({short_json(inp)})")
        return
    if name=='map_values':
        if not args: raise JQError('map_values requires an argument')
        if isinstance(inp,list):
            arr=[]
            for x in inp:
                outs=list(args[0].eval(ctx,x))
                if outs: arr.append(outs[0])
            yield arr
        elif isinstance(inp,dict):
            obj=OrderedDict()
            for k,x in inp.items():
                outs=list(args[0].eval(ctx,x))
                if outs: obj[k]=outs[0]
            yield obj
        else: raise JQError(f"Cannot iterate over {type_name(inp)} ({short_json(inp)})")
        return
    if name=='select':
        if not args: return
        for c in args[0].eval(ctx, inp):
            if jq_truth(c): yield inp
        return
    if name=='add':
        if isinstance(inp,list):
            if not inp: yield None
            else:
                acc=inp[0]
                for x in inp[1:]: acc=jq_add(acc,x)
                yield acc
        elif isinstance(inp,dict):
            vals=list(inp.values())
            if not vals: yield None
            else:
                acc=vals[0]
                for x in vals[1:]: acc=jq_add(acc,x)
                yield acc
        else: raise JQError(f"Cannot iterate over {type_name(inp)} ({short_json(inp)})")
        return
    if name in ('min','max'):
        seq=list(inp.values()) if isinstance(inp,dict) else inp
        if not isinstance(seq,list): raise JQError(f"Cannot iterate over {type_name(inp)} ({short_json(inp)})")
        if not seq: yield None
        else: yield sorted(seq, key=sort_key)[0 if name=='min' else -1]
        return
    if name in ('sort','unique','reverse'):
        if not isinstance(inp,list): raise JQError(f"Cannot iterate over {type_name(inp)} ({short_json(inp)})")
        if name=='reverse': yield list(reversed(inp)); return
        arr=sorted(inp,key=sort_key)
        if name=='unique':
            out=[]
            for x in arr:
                if not out or not jq_equal(out[-1],x): out.append(x)
            yield out
        else: yield arr
        return
    if name in ('sort_by','group_by','min_by','max_by','unique_by'):
        if not args: raise JQError(f'{name} requires an argument')
        if not isinstance(inp,list): raise JQError(f"Cannot iterate over {type_name(inp)} ({short_json(inp)})")
        keyed=[]
        for x in inp:
            kvs=list(args[0].eval(ctx,x)); key=kvs[0] if kvs else None
            keyed.append((key,x))
        keyed.sort(key=lambda kv: sort_key(kv[0]))
        if name=='sort_by': yield [x for k,x in keyed]
        elif name=='min_by': yield (keyed[0][1] if keyed else None)
        elif name=='max_by': yield (keyed[-1][1] if keyed else None)
        elif name=='unique_by':
            out=[]; last=object()
            for k,x in keyed:
                if not out or not jq_equal(k,last): out.append(x); last=k
            yield out
        else:
            groups=[]
            for k,x in keyed:
                if not groups or not jq_equal(groups[-1][0], k): groups.append((k,[x]))
                else: groups[-1][1].append(x)
            yield [g for k,g in groups]
        return
    if name=='flatten':
        depth=None
        if args: 
            d=first_arg_value(args[0],ctx,inp)
            depth=int(d.dec) if isinstance(d,JQNumber) else None
        if not isinstance(inp,list): raise JQError(f"Cannot iterate over {type_name(inp)} ({short_json(inp)})")
        yield flatten(inp, depth); return
    if name=='range':
        vals=[]
        if len(args)==0:
            return
        elif len(args)==1:
            for end in args[0].eval(ctx,inp):
                yield from gen_range(JQNumber(0), end, JQNumber(1))
        elif len(args)==2:
            starts=list(args[0].eval(ctx,inp)); ends=list(args[1].eval(ctx,inp))
            for s in starts:
                for e in ends: yield from gen_range(s,e,JQNumber(1))
        else:
            starts=list(args[0].eval(ctx,inp)); ends=list(args[1].eval(ctx,inp)); steps=list(args[2].eval(ctx,inp))
            for s in starts:
                for e in ends:
                    for st in steps: yield from gen_range(s,e,st)
        return
    if name in ('tonumber','tostring','tojson','fromjson'):
        if name=='tostring': yield jq_tostring(inp)
        elif name=='tojson': yield dump_json(inp, compact=True, ensure_ascii=False)
        elif name=='fromjson':
            if not isinstance(inp,str): raise JQError('fromjson requires string inputs')
            yield parse_one_json(inp)
        else:
            if isinstance(inp,JQNumber): yield inp
            elif isinstance(inp,str):
                try: yield JQNumber(inp)
                except Exception: raise JQError(f"Invalid numeric literal")
            else: raise JQError(f"{type_name(inp)} ({short_json(inp)}) cannot be parsed as a number")
        return
    if name in ('floor','ceil','round','trunc','sqrt','abs'):
        d=as_dec(inp)
        if name=='floor': yield JQNumber(d.to_integral_value(rounding=ROUND_FLOOR))
        elif name=='ceil': yield JQNumber(d.to_integral_value(rounding=ROUND_CEILING))
        elif name=='round': yield JQNumber(Decimal(int(d.to_integral_value())))
        elif name=='trunc': yield JQNumber(Decimal(int(d)))
        elif name=='sqrt': yield JQNumber(Decimal(str(math.sqrt(float(d)))))
        elif name=='abs': yield JQNumber(abs(d))
        return
    if name in ('contains','startswith','endswith'):
        arg=first_arg_value(args[0] if args else None,ctx,inp)
        if name=='contains': yield jq_contains(inp,arg)
        elif name=='startswith': yield isinstance(inp,str) and isinstance(arg,str) and inp.startswith(arg)
        else: yield isinstance(inp,str) and isinstance(arg,str) and inp.endswith(arg)
        return
    if name in ('index','rindex','indices'):
        arg=first_arg_value(args[0] if args else None,ctx,inp)
        res=jq_indices(inp,arg)
        if name=='indices': yield [JQNumber(i) for i in res]
        elif name=='index': yield (JQNumber(res[0]) if res else None)
        else: yield (JQNumber(res[-1]) if res else None)
        return
    if name=='split':
        sep=first_arg_value(args[0] if args else None,ctx,inp)
        if not isinstance(inp,str) or not isinstance(sep,str): raise JQError('split input and separator must be strings')
        yield inp.split(sep); return
    if name=='join':
        sep=first_arg_value(args[0] if args else None,ctx,inp)
        if not isinstance(inp,list): raise JQError(f"Cannot iterate over {type_name(inp)} ({short_json(inp)})")
        yield str(sep).join(join_elem(x) for x in inp); return
    if name=='explode':
        if not isinstance(inp,str): raise JQError('explode input must be a string')
        yield [JQNumber(ord(ch)) for ch in inp]; return
    if name=='implode':
        if not isinstance(inp,list): raise JQError('implode input must be an array')
        yield ''.join(chr(int(as_dec(x))) for x in inp); return
    if name in ('ascii_downcase','ascii_upcase'):
        if not isinstance(inp,str): raise JQError(f"{type_name(inp)} ({short_json(inp)}) cannot be case-converted")
        yield ''.join((ch.lower() if ord(ch)<128 else ch) for ch in inp) if name.endswith('downcase') else ''.join((ch.upper() if ord(ch)<128 else ch) for ch in inp)
        return
    if name in ('ltrimstr','rtrimstr'):
        s=first_arg_value(args[0] if args else None,ctx,inp)
        if not isinstance(inp,str) or not isinstance(s,str): raise JQError('trim requires strings')
        if name=='ltrimstr' and inp.startswith(s): yield inp[len(s):]
        elif name=='rtrimstr' and inp.endswith(s): yield inp[:-len(s)] if s else inp
        else: yield inp
        return
    if name=='to_entries': yield to_entries(inp); return
    if name=='from_entries': yield from_entries(inp); return
    if name=='with_entries':
        arr=to_entries(inp); out=[]
        for e in arr:
            out.extend(args[0].eval(ctx,e))
        yield from_entries(out); return
    if name=='path':
        if not args: yield []
        else:
            for p in args[0].paths(ctx, inp):
                yield [JQNumber(x) if isinstance(x,int) else x for x in p]
        return
    if name=='paths':
        pred=args[0] if args else None
        for p in enumerate_paths(inp):
            val=get_path(inp,p,missing_none=True)
            if pred is not None:
                good=False
                for c in pred.eval(ctx,val):
                    if jq_truth(c): good=True; break
                if not good: continue
            yield [JQNumber(x) if isinstance(x,int) else x for x in p]
        return
    if name=='getpath':
        p=path_arg(first_arg_value(args[0] if args else None,ctx,inp,[]))
        yield get_path(inp,p,missing_none=True); return
    if name=='setpath':
        p=path_arg(first_arg_value(args[0] if args else None,ctx,inp,[]))
        val=first_arg_value(args[1] if len(args)>1 else None,ctx,inp)
        yield set_path(deepcopy_jq(inp), p, val); return
    if name=='delpaths':
        paths=first_arg_value(args[0] if args else None,ctx,inp,[])
        root=deepcopy_jq(inp)
        # Delete deeper and higher indexes first.
        ps=[path_arg(p) for p in paths]
        ps.sort(key=lambda p:(len(p), p), reverse=True)
        for p in ps: root=del_path(root,p)
        yield root; return
    if name=='del':
        root=deepcopy_jq(inp)
        if args:
            ps=args[0].paths(ctx, inp)
            ps.sort(key=lambda p:(len(p), p), reverse=True)
            for p in ps: root=del_path(root,p)
        yield root; return
    if name in ('input','inputs'):
        if ctx.inputs is None: return
        if name=='input': yield ctx.inputs.next()
        else:
            yield from ctx.inputs.rest()
        return
    if name in ('first','last'):
        if args:
            vals=list(args[0].eval(ctx,inp))
        else:
            vals=inp if isinstance(inp,list) else list(inp.values()) if isinstance(inp,dict) else []
        if vals: yield vals[0 if name=='first' else -1]
        return
    if name=='nth':
        if len(args)==1:
            n=first_arg_value(args[0],ctx,inp); vals=inp if isinstance(inp,list) else []
        else:
            n=first_arg_value(args[0],ctx,inp); vals=list(args[1].eval(ctx,inp))
        idx=int(as_dec(n));
        if 0<=idx<len(vals): yield vals[idx]
        return
    if name in ('any','all'):
        yield eval_any_all(name,args,ctx,inp); return
    if name=='recurse':
        f=args[0] if args else FuncCall('children',[])
        yield from recurse_values(ctx, inp, f); return
    if name=='children':
        if isinstance(inp,list):
            for x in inp: yield x
        elif isinstance(inp,dict):
            for x in inp.values(): yield x
        return
    if name=='transpose':
        if not isinstance(inp,list): raise JQError('transpose input must be an array')
        maxlen=max((len(x) for x in inp if isinstance(x,list)), default=0)
        out=[]
        for i in range(maxlen): out.append([row[i] if isinstance(row,list) and i<len(row) else None for row in inp])
        yield out; return
    if name=='error':
        msg=jq_tostring(first_arg_value(args[0],ctx,inp) if args else inp)
        raise JQError(msg)
    if name in ('halt','halt_error'):
        code=0 if name=='halt' else int(as_dec(first_arg_value(args[0],ctx,inp,JQNumber(5)) if args else JQNumber(5)))
        raise HaltException(code)
    if name=='break':
        raise JQError('break')
    if name=='nan': yield None; return
    if name=='infinite': yield JQNumber('1.7976931348623157e+308'); return
    if name=='now': yield JQNumber(Decimal(str(time.time()))); return
    if name=='env': yield OrderedDict((k,v) for k,v in os.environ.items()); return
    if name=='debug':
        print('["DEBUG:",'+dump_json(inp,compact=True)+']', file=sys.stderr)
        yield inp; return
    # Regex-ish functions: a small Python re implementation.
    if name in ('test','match','capture','sub','gsub'):
        yield from regex_func(name,args,ctx,inp); return

    raise JQCompileError(f"{name}/{len(args)} is not defined")


def builtin_length(v):
    if v is None: return JQNumber(0)
    if isinstance(v,JQNumber): return JQNumber(abs(v.dec))
    if isinstance(v,str): return JQNumber(len(v))
    if isinstance(v,(list,dict)): return JQNumber(len(v))
    if isinstance(v,bool): raise JQError(f"boolean ({str(v).lower()}) has no length")
    raise JQError(f"{type_name(v)} has no length")

def builtin_keys(v, sorted_keys=True):
    if isinstance(v,list): return [JQNumber(i) for i in range(len(v))]
    if isinstance(v,dict):
        ks=list(v.keys())
        if sorted_keys: ks=sorted(ks)
        return ks
    raise JQError(f"{type_name(v)} ({short_json(v)}) has no keys")

def builtin_has(obj,key):
    if isinstance(key,JQNumber): key=int(key.dec)
    if isinstance(obj,dict) and isinstance(key,str): return key in obj
    if isinstance(obj,list) and isinstance(key,int): return 0 <= key < len(obj)
    return False

def flatten(arr, depth):
    out=[]
    for x in arr:
        if isinstance(x,list) and (depth is None or depth>0):
            out.extend(flatten(x, None if depth is None else depth-1))
        else: out.append(x)
    return out

def gen_range(s,e,st):
    sd,ed,std=as_dec(s),as_dec(e),as_dec(st)
    if std == 0: return
    x=sd
    if std > 0:
        while x < ed:
            yield JQNumber(x); x += std
    else:
        while x > ed:
            yield JQNumber(x); x += std

def jq_contains(a,b):
    if isinstance(a,str) and isinstance(b,str): return b in a
    if isinstance(a,list):
        if isinstance(b,list): return all(any(jq_contains(x,y) for x in a) for y in b)
        return any(jq_contains(x,b) for x in a)
    if isinstance(a,dict) and isinstance(b,dict):
        return all(k in a and jq_contains(a[k],v) for k,v in b.items())
    return jq_equal(a,b)

def jq_indices(a,b):
    res=[]
    if isinstance(a,str) and isinstance(b,str):
        start=0
        while True:
            i=a.find(b,start)
            if i<0: break
            res.append(i); start=i+1 if b else i+1
            if b=='' and start>len(a): break
    elif isinstance(a,list):
        pat=b if isinstance(b,list) else [b]
        if not pat: return list(range(len(a)+1))
        for i in range(0,len(a)-len(pat)+1):
            if all(jq_equal(a[i+j],pat[j]) for j in range(len(pat))): res.append(i)
    return res

def join_elem(x):
    if x is None: return ''
    if isinstance(x,str): return x
    if isinstance(x,bool): return 'true' if x else 'false'
    if isinstance(x,JQNumber): return x.raw
    return dump_json(x, compact=True, ensure_ascii=False)

def to_entries(v):
    if isinstance(v,dict): return [OrderedDict([('key',k),('value',val)]) for k,val in v.items()]
    if isinstance(v,list): return [OrderedDict([('key',JQNumber(i)),('value',val)]) for i,val in enumerate(v)]
    raise JQError(f"{type_name(v)} ({short_json(v)}) cannot be converted to entries")

def from_entries(arr):
    if not isinstance(arr,list): raise JQError('from_entries requires an array')
    obj=OrderedDict()
    for e in arr:
        if not isinstance(e,dict): continue
        key=e.get('key', e.get('Key', e.get('name', e.get('Name'))))
        val=e.get('value', e.get('Value'))
        if isinstance(key,JQNumber): key=key.raw
        obj[str(key)]=val
    return obj

def enumerate_paths(v, prefix=None):
    prefix=prefix or []
    if isinstance(v,dict):
        for k,val in v.items():
            p=prefix+[k]; yield p
            yield from enumerate_paths(val,p)
    elif isinstance(v,list):
        for i,val in enumerate(v):
            p=prefix+[i]; yield p
            yield from enumerate_paths(val,p)

def path_arg(p):
    out=[]
    if not isinstance(p,list): return out
    for x in p:
        if isinstance(x,JQNumber): out.append(int(x.dec))
        else: out.append(x)
    return out

def eval_any_all(name,args,ctx,inp):
    vals=[]
    if len(args)==0:
        vals = inp if isinstance(inp,list) else list(inp.values()) if isinstance(inp,dict) else []
        bools=[jq_truth(v) for v in vals]
    elif len(args)==1:
        if isinstance(inp,list):
            bools=[]
            for x in inp:
                outs=list(args[0].eval(ctx,x)); bools.extend(jq_truth(o) for o in outs)
        else:
            bools=[jq_truth(o) for o in args[0].eval(ctx,inp)]
    else:
        bools=[]
        for x in args[0].eval(ctx,inp):
            bools.extend(jq_truth(o) for o in args[1].eval(ctx,x))
    return any(bools) if name=='any' else all(bools)

def recurse_values(ctx, inp, f):
    yield inp
    for child in f.eval(ctx, inp):
        yield from recurse_values(ctx, child, f)

def format_value(fmt, inp):
    if fmt=='json': return dump_json(inp, compact=True, ensure_ascii=False)
    if fmt=='text': return jq_tostring(inp)
    if fmt=='uri': return urllib.parse.quote(jq_tostring(inp), safe='')
    if fmt=='base64': return base64.b64encode(jq_tostring(inp).encode()).decode()
    if fmt=='base64d':
        if not isinstance(inp,str): raise JQError(f"{type_name(inp)} ({short_json(inp)}) is not valid base64 data")
        try: return base64.b64decode(inp).decode()
        except Exception: raise JQError(f"string ({short_json(inp)}) is not valid base64 data")
    if fmt in ('csv','tsv'):
        if not isinstance(inp,list): raise JQError(f"{type_name(inp)} ({short_json(inp)}) cannot be {fmt}-formatted, only array")
        vals=[]
        for x in inp:
            if x is None: vals.append('')
            elif isinstance(x,str): vals.append(x)
            else: vals.append(jq_tostring(x))
        if fmt=='tsv':
            return '\t'.join(v.replace('\\','\\\\').replace('\t','\\t').replace('\n','\\n').replace('\r','\\r') for v in vals)
        sio=io.StringIO(); w=csv.writer(sio, lineterminator='') ; w.writerow(vals); return sio.getvalue()
    if fmt=='sh':
        vals=inp if isinstance(inp,list) else [inp]
        if not isinstance(vals,list): vals=[vals]
        def q(s): return "'" + str(s).replace("'", "'\\''") + "'"
        return ' '.join(q(jq_tostring(x)) for x in vals)
    return jq_tostring(inp)

def regex_func(name,args,ctx,inp):
    if not isinstance(inp,str): raise JQError(f"{type_name(inp)} ({short_json(inp)}) cannot be matched, as it is not a string")
    pat=first_arg_value(args[0] if args else None,ctx,inp,'')
    flags=''
    if len(args)>1: flags=first_arg_value(args[1],ctx,inp,'')
    re_flags=0
    if isinstance(flags,str) and 'i' in flags: re_flags|=re.I
    try: rgx=re.compile(str(pat), re_flags)
    except re.error as e: raise JQError(str(e))
    if name=='test': yield rgx.search(inp) is not None; return
    if name=='match':
        for m in rgx.finditer(inp):
            caps=[]
            for g in m.groups(): caps.append(OrderedDict([('offset',JQNumber(-1 if g is None else m.start(m.groups().index(g)+1))),('length',JQNumber(0 if g is None else len(g))),('string',g)]))
            yield OrderedDict([('offset',JQNumber(m.start())),('length',JQNumber(m.end()-m.start())),('string',m.group(0)),('captures',caps)])
        return
    if name=='capture':
        m=rgx.search(inp)
        if not m: return
        yield OrderedDict((k,v) for k,v in m.groupdict().items()); return
    if name in ('sub','gsub'):
        repl=first_arg_value(args[1] if len(args)>1 else None,ctx,inp,'')
        count=1 if name=='sub' else 0
        yield rgx.sub(str(repl), inp, count=count); return

# ---------------------------- CLI ----------------------------

@dataclass
class Options:
    null_input: bool=False
    raw_input: bool=False
    slurp: bool=False
    compact: bool=False
    raw_output: bool=False
    raw_output0: bool=False
    join_output: bool=False
    ascii_output: bool=False
    sort_keys: bool=False
    color: bool=False
    mono: bool=False
    tab: bool=False
    indent: int=2
    unbuffered: bool=False
    stream: bool=False
    stream_errors: bool=False
    seq: bool=False
    exit_status: bool=False
    filter_file: Optional[str]=None


def option_error(msg):
    print(f"jq: {msg}", file=sys.stderr)
    print("Use jq --help for help with command-line options,", file=sys.stderr)
    print("or see the jq manpage, or online docs at https://jqlang.org", file=sys.stderr)
    return 2


def parse_cli(argv):
    opts=Options(); vars={}; named=OrderedDict(); positional=[]; files=[]; filter_src=None
    i=0; literal_mode=False
    while i < len(argv):
        a=argv[i]
        if a=='--args' or a=='--jsonargs':
            jsonmode=(a=='--jsonargs')
            rest=argv[i+1:]
            if filter_src is None and rest:
                filter_src=rest[0]; rest=rest[1:]
            for x in rest:
                if jsonmode:
                    try: positional.append(parse_one_json(x))
                    except Exception: return opts, vars, named, positional, files, filter_src, option_error('invalid JSON text passed to --jsonargs')
                else: positional.append(x)
            i=len(argv); break
        if not literal_mode and a=='--':
            literal_mode=True; i+=1; continue
        if not literal_mode and a.startswith('--') and a!='--':
            if a in ('--null-input',): opts.null_input=True
            elif a=='--raw-input': opts.raw_input=True
            elif a=='--slurp': opts.slurp=True
            elif a=='--compact-output': opts.compact=True
            elif a=='--raw-output': opts.raw_output=True
            elif a=='--raw-output0': opts.raw_output=True; opts.raw_output0=True
            elif a=='--join-output': opts.raw_output=True; opts.join_output=True
            elif a=='--ascii-output': opts.ascii_output=True
            elif a=='--sort-keys': opts.sort_keys=True
            elif a=='--color-output': opts.color=True
            elif a=='--monochrome-output': opts.mono=True; opts.color=False
            elif a=='--tab': opts.tab=True; opts.indent=-1
            elif a=='--unbuffered': opts.unbuffered=True
            elif a=='--stream': opts.stream=True
            elif a=='--stream-errors': opts.stream=True; opts.stream_errors=True
            elif a=='--seq': opts.seq=True
            elif a=='--exit-status': opts.exit_status=True
            elif a in ('--version',): print(VERSION); sys.exit(0)
            elif a=='--build-configuration': print(BUILD_CONFIG); sys.exit(0)
            elif a in ('--help',): print(HELP_TEXT, end=''); sys.exit(0)
            elif a=='--indent':
                i+=1
                if i>=len(argv): return opts,vars,named,positional,files,filter_src, option_error('--indent takes a number between -1 and 7')
                try: ind=int(argv[i])
                except: return opts,vars,named,positional,files,filter_src, option_error('--indent takes a number between -1 and 7')
                if ind < -1 or ind > 7: return opts,vars,named,positional,files,filter_src, option_error('--indent takes a number between -1 and 7')
                opts.indent=ind; opts.tab=(ind==-1)
            elif a in ('--from-file','--arg','--argjson','--slurpfile','--rawfile','--library-path'):
                if a=='--from-file':
                    i+=1
                    if i>=len(argv): return opts,vars,named,positional,files,filter_src, option_error('--from-file takes a filename')
                    opts.filter_file=argv[i]
                elif a=='--library-path':
                    i+=1
                elif a=='--arg':
                    if i+2>=len(argv): return opts,vars,named,positional,files,filter_src, option_error('--arg takes two parameters')
                    name,val=argv[i+1],argv[i+2]; i+=2; vars[name]=val; named[name]=val
                elif a=='--argjson':
                    if i+2>=len(argv): return opts,vars,named,positional,files,filter_src, option_error('--argjson takes two parameters')
                    name,val=argv[i+1],argv[i+2]; i+=2
                    try: jv=parse_one_json(val)
                    except Exception: return opts,vars,named,positional,files,filter_src, option_error('invalid JSON text passed to --argjson')
                    vars[name]=jv; named[name]=jv
                elif a=='--slurpfile':
                    if i+2>=len(argv): return opts,vars,named,positional,files,filter_src, option_error('--slurpfile takes two parameters')
                    name,fn=argv[i+1],argv[i+2]; i+=2
                    try: txt=open(fn,'r',encoding='utf-8').read(); vals=parse_json_values(txt)
                    except FileNotFoundError: return opts,vars,named,positional,files,filter_src, option_error(f"Could not open {fn}: No such file or directory")
                    except Exception: vals=[]
                    vars[name]=vals; named[name]=vals
                elif a=='--rawfile':
                    if i+2>=len(argv): return opts,vars,named,positional,files,filter_src, option_error('--rawfile takes two parameters')
                    name,fn=argv[i+1],argv[i+2]; i+=2
                    try: val=open(fn,'r',encoding='utf-8').read()
                    except FileNotFoundError: return opts,vars,named,positional,files,filter_src, option_error(f"Could not open {fn}: No such file or directory")
                    vars[name]=val; named[name]=val
            else:
                return opts,vars,named,positional,files,filter_src, option_error(f"Unknown option {a}")
            i+=1; continue
        if not literal_mode and a.startswith('-') and a != '-':
            # short option bundle; options requiring args consume following argv.
            j=1
            while j < len(a):
                ch=a[j]
                if ch=='n': opts.null_input=True
                elif ch=='R': opts.raw_input=True
                elif ch=='s': opts.slurp=True
                elif ch=='c': opts.compact=True
                elif ch=='r': opts.raw_output=True
                elif ch=='j': opts.raw_output=True; opts.join_output=True
                elif ch=='a': opts.ascii_output=True
                elif ch=='S': opts.sort_keys=True
                elif ch=='C': opts.color=True
                elif ch=='M': opts.mono=True; opts.color=False
                elif ch=='e': opts.exit_status=True
                elif ch=='V': print(VERSION); sys.exit(0)
                elif ch=='h': print(HELP_TEXT,end=''); sys.exit(0)
                elif ch=='f':
                    if j != len(a)-1:
                        opts.filter_file=a[j+1:]; j=len(a); break
                    i+=1
                    if i>=len(argv): return opts,vars,named,positional,files,filter_src, option_error('-f takes a filename')
                    opts.filter_file=argv[i]; break
                elif ch=='L':
                    if j == len(a)-1: i+=1
                    break
                else:
                    return opts,vars,named,positional,files,filter_src, option_error(f"Unknown option -{ch}")
                j+=1
            i+=1; continue
        # Non-option: first is filter unless -f was used; rest are files.
        if filter_src is None and opts.filter_file is None:
            filter_src=a
        else:
            files.append(a)
        i+=1
    if opts.filter_file is not None:
        try: filter_src=open(opts.filter_file,'r',encoding='utf-8').read()
        except FileNotFoundError:
            print(f"jq: Could not open {opts.filter_file}: No such file or directory", file=sys.stderr)
            return opts,vars,named,positional,files,filter_src,2
    vars['ARGS']=OrderedDict([('positional', positional), ('named', named)])
    return opts, vars, named, positional, files, filter_src, None


def read_input_values(opts, files):
    # Return values for initial/input builtins.  -n uses no initial consumption but
    # input/inputs still read according to raw/slurp settings.
    texts=[]
    if files:
        for fn in files:
            try:
                with open(fn,'r',encoding='utf-8') as f: texts.append(f.read())
            except FileNotFoundError:
                print(f"jq: error: Could not open file {fn}: No such file or directory", file=sys.stderr)
                raise SystemExit(2)
    else:
        texts=[sys.stdin.read()]
